#include "../inflection.hpp"
#include <iostream>
#include <vector>
#include <cstdlib>

int main(int argc, char* argv[]) {
    inflection::Inflector::initialize();

    // 20个API调用 - 最复杂的测试
    std::vector<std::string> allResults;

    // 收集所有可能的转换
    if (argc > 1) {
        std::string baseWord = argv[1];

        // 1-5: 基本转换
        allResults.push_back(inflection::Inflector::pluralize(baseWord));
        allResults.push_back(inflection::Inflector::singularize(baseWord));
        allResults.push_back(inflection::Inflector::camelize(baseWord));
        allResults.push_back(inflection::Inflector::camelize(baseWord, false));
        allResults.push_back(inflection::Inflector::underscore(baseWord));

