        allResults.push_back(inflection::Inflector::tableize(baseWord));
        allResults.push_back(inflection::Inflector::humanize(baseWord));
        allResults.push_back(inflection::Inflector::titleize(baseWord));
        allResults.push_back(inflection::Inflector::dasherize(baseWord));

        // 11-15: 参数化和其他
        allResults.push_back(inflection::Inflector::parameterize(baseWord));
        allResults.push_back(inflection::Inflector::parameterize("A " + baseWord + " Test"));
        allResults.push_back(inflection::Inflector::upcase(baseWord));
        allResults.push_back(inflection::Inflector::downcase(baseWord));
        allResults.push_back(inflection::Inflector::capitalize(baseWord));

        // 16-20: 额外功能
        allResults.push_back(inflection::Inflector::decapitalize(baseWord));
        allResults.push_back(inflection::Inflector::truncate(baseWord, 5));
        allResults.push_back(inflection::Inflector::demodulize("Test::" + baseWord));
        allResults.push_back(std::to_string(inflection::Inflector::isPlural(baseWord)));
        allResults.push_back(std::to_string(inflection::Inflector::isSingular(baseWord)));
    }

    // 如果参数不足，使用默认值
    if (allResults.size() < 20 && argc > 1) {
        // 使用序数
        for (int i = 1; i <= 5 && allResults.size() < 20; i++) {
            allResults.push_back(inflection::Inflector::ordinalize(i));
        }
    }

    // 输出正好20个结果
    for (size_t i = 0; i < 20 && i < allResults.size(); i++) {
        std::cout << allResults[i] << std::endl;
    }

    return 0;
}


